	inline function node( name : String, ?props : Array<FbxProp>, ?childs : Array<FbxNode> ) : FbxNode {
		return { name : name, props : props == null ? [] : props, childs : childs == null ? [] : childs };
	}

	function writeNode( n : FbxNode, indent : String ) {
		switch( n.props.length ) {
		case 0:
			if( n.childs.length == 0 )
				out.writeString(indent + n.name + ";\n");
			else {
				out.writeString(indent + n.name + " {\n");
				for( c in n.childs )
					writeNode(c, indent + "\t");
				out.writeString(indent + "}\n");
			}
		case 1:
			var arr : FbxProp = null;
			switch( n.props[0] ) {
			case PInts(_), PFloats(_):
