	function parseGeometry( g : hxd.fmt.hmd.Geometry ) : { rows : Array<Float>, stride : Int, posOff : Int, normOff : Int, uvOffs : Array<Int> } {
		if( data.data == null ) throw "Missing geometry data";
		var inputs = g.vertexFormat.getInputs();
		var stride = 0;
		var posOff = -1, normOff = -1;
		var uvOffs = [];
		for( i in inputs ) {
			if( i.name == "position" ) posOff = stride;
			if( i.name == "normal" ) normOff = stride;
			if( i.name.indexOf("uv") == 0 ) uvOffs.push(stride);
			stride += i.type.getSize();
		}
		if( posOff < 0 ) throw "Missing position in geometry format";
		var rows = new Array<Float>();
		rows.resize(g.vertexCount * stride);
		var p = 0;
		for( v in 0...g.vertexCount ) {
			var pos = g.vertexPosition + v * g.vertexFormat.strideBytes;
			for( i in inputs ) {
				var comps = i.type.getSize();
				var esz = i.precision.getSize();
				for( k in 0...comps ) {
					var f = switch( i.precision ) {
					case F32: data.data.getFloat(pos);
					case F16: hxd.BufferFormat.float16to32(data.data.getUInt16(pos));
					case U8: hxd.BufferFormat.floatU8to32(data.data.get(pos));
					case S8: hxd.BufferFormat.floatS8to32(data.data.get(pos));
					}
					rows[p++] = f;
					pos += esz;
				}
				if( pos & 3 != 0 )
					pos += 4 - (pos & 3);
			}
		}
		return { rows : rows, stride : stride, posOff : posOff, normOff : normOff, uvOffs : uvOffs };
	}
```

