package hxd.fmt.fbx;

import h3d.Quat;
using hxd.fmt.fbx.Data;

/**
	Writes an `hxd.fmt.hmd.Data` scene into the FBX 7.3.0 ASCII format.

	The exporter converts HMD models, their hierarchy/transforms and mesh
	geometry into FBX `Model`, `Geometry` and `Material` objects. Meshes with
	multiple sub-meshes (one per material) are split into as many independent
	FBX `Geometry` objects sharing the same `Model`.
**/
class Writer {

	var out : haxe.io.Output;
	var data : hxd.fmt.hmd.Data;
	var objects : FbxNode;
	var connections : Array<FbxNode>;
	var modelIds : Array<Int>;
	var geometryIds : Map<String,Int>;
	var materialIds : Map<Int,Int>;
	var nextId : Int;
	var modelCount : Int;
	var geometryCount : Int;
	var materialCount : Int;

	public function new(out : haxe.io.Output) {
		this.out = out;
	}

	// ---------------- low level output ----------------

	inline function node(name : String, ?props : Array<FbxProp>, ?childs : Array<FbxNode>) : FbxNode {
		return { name : name, props : props == null ? [] : props, childs : childs == null ? [] : childs };
	}

	function writeNode(n : FbxNode, indent : String) {
		switch( n.props.length ) {
		case 0:
			if( n.childs.length == 0 )
				out.writeString(indent + n.name + ";\n");
			else {
				out.writeString(indent + n.name + " {\n");
				for( c in n.childs )
					writeNode(c, indent + "\t");
				out.writeString(indent + "}\n");
			}
		case 1:
			var arr : FbxProp = null;
			switch( n.props[0] ) {
			case PInts(_), PFloats(_): arr = n.props[0];
			default:
			}
			if( arr != null ) {
				var count = switch( arr ) {
				case PInts(v): v.length;
				case PFloats(v): v.length;
				default: 0;
				}
				out.writeString(indent + n.name + ": *" + count + " {\n");
				out.writeString(indent + "\ta: " + writeProperty(arr) + "\n");
				out.writeString(indent + "}\n");
				for( c in n.childs )
					writeNode(c, indent);
				return;
			}
			writeNodeProps(n, indent);
		default:
			writeNodeProps(n, indent);
		}
	}

	function writeNodeProps(n : FbxNode, indent : String) {
		var props = "";
		for( p in n.props )
			props += " " + writeProperty(p);
		if( n.childs.length == 0 )
			out.writeString(indent + n.name + props + ";\n");
		else {
			out.writeString(indent + n.name + props + " {\n");
			for( c in n.childs )
				writeNode(c, indent + "\t");
			out.writeString(indent + "}\n");
		}
	}

	function writeProperty(p : FbxProp) : String {
		return switch( p ) {
		case PInt(v): "" + v;
		case PFloat(v): formatFloat(v);
		case PString(v): '"' + v + '"';
		case PIdent(i): i;
		case PInts(v): [for( x in v ) "" + x].join(",");
		case PFloats(v): [for( x in v ) formatFloat(x)].join(",");
		case PBinary(_): throw "Binary properties are not supported";
		}
	}

	inline function formatFloat(v : Float) : String {
		// make sure the value is stored with a float representation
		var s = Std.string(v);
		if( s.indexOf(".") < 0 && s.indexOf("e") < 0 && s.indexOf("E") < 0 )
			s += ".0";
		return s;
	}

	// ---------------- scene headers ----------------

	function buildTimeStampNode() : FbxNode {
		var t = Date.now();
		return node("CreationTimeStamp", null, [
			node("Version", [PInt(1000)]),
			node("Year", [PInt(t.getFullYear())]),
			node("Month", [PInt(t.getMonth() + 1)]),
			node("Day", [PInt(t.getDate())]),
			node("Hour", [PInt(t.getHours())]),
			node("Minute", [PInt(t.getMinutes())]),
			node("Second", [PInt(t.getSeconds())]),
			node("Millisecond", [PInt(t.getMilliseconds())]),
		]);
	}

	function buildSceneInfoNode() : FbxNode {
		return node("SceneInfo", null, [
			node("Type", [PString("UserData")]),
			node("Version", [PInt(100)]),
			node("MetaData", null, [
				node("Version", [PInt(100)]),
				node("Title", [PString("")]),
				node("Subject", [PString("")]),
				node("Author", [PString("")]),
				node("Keywords", [PString("")]),
				node("Revision", [PString("")]),
				node("Comment", [PString("")]),
			]),
			node("Properties70", null, []),
		]);
	}

	function buildHeaderNode() : FbxNode {
		return node("FBXHeaderExtension", null, [
			node("FBXHeaderVersion", [PInt(1003)]),
			node("FBXVersion", [PInt(7300)]),
			node("Creator", [PString('Heaps Framework - FBX Writer')]),
			buildTimeStampNode(),
			buildSceneInfoNode(),
		]);
	}

	function buildGlobalSettingsNode() : FbxNode {
		return node("GlobalSettings", null, [
			node("Version", [PInt(1000)]),
			node("Properties70", null, [
				node("P", [PString("UpAxis"), PString("int"), PString("Integer"), PString(""), PInt(1)]),
				node("P", [PString("UpAxisSign"), PString("int"), PString("Integer"), PString(""), PInt(1)]),
				node("P", [PString("FrontAxis"), PString("int"), PString("Integer"), PString(""), PInt(2)]),
				node("P", [PString("FrontAxisSign"), PString("int"), PString("Integer"), PString(""), PInt(1)]),
				node("P", [PString("CoordAxis"), PString("int"), PString("Integer"), PString(""), PInt(1)]),
				node("P", [PString("CoordAxisSign"), PString("int"), PString("Integer"), PString(""), PInt(1)]),
				node("P", [PString("OriginalUpAxis"), PString("int"), PString("Integer"), PString(""), PInt(2)]),
				node("P", [PString("OriginalUpAxisSign"), PString("int"), PString("Integer"), PString(""), PInt(1)]),
				node("P", [PString("UnitScaleFactor"), PString("double"), PString("Number"), PString(""), PFloat(1)]),
				node("P", [PString("OriginalUnitScaleFactor"), PString("double"), PString("Number"), PString(""), PFloat(1)]),
				node("P", [PString("AmbientColor"), PString("ColorRGB"), PString("Color"), PString(""), PFloat(0), PFloat(0), PFloat(0)]),
				node("P", [PString("DefaultCamera"), PString("KString"), PString(""), PString(""), PString("Producer Perspective")]),
			]),
		]);
	}

	function writeDefinitions() : FbxNode {
		var defs = node("Definitions", null, [
			node("Version", [PInt(100)]),
			node("Count", [PInt(1 + modelCount + geometryCount + materialCount)]),
		]);
		defs.childs.push(node("ObjectType", [PString("GlobalSettings")], [node("Count", [PInt(1)])]));
		defs.childs.push(node("ObjectType", [PString("Model")], [node("Count", [PInt(modelCount)])]));
		defs.childs.push(node("ObjectType", [PString("Geometry")], [node("Count", [PInt(geometryCount)])]));
		defs.childs.push(node("ObjectType", [PString("Material")], [node("Count", [PInt(materialCount)])]));
		return defs;
	}

	// ---------------- transforms ----------------

	function quatToEuler(q : Quat) : { x : Float, y : Float, z : Float } {
		var m = new h3d.Matrix();
		q.toMatrix(m);
		// invert the left-handed conversion applied by the FBX importer
		m._12 = -m._12;
		m._13 = -m._13;
		m._21 = -m._21;
		m._31 = -m._31;
		var sy = -m._13;
		if( sy > 1 ) sy = 1;
		if( sy < -1 ) sy = -1;
		var out = { x : Math.atan2(m._23, m._33), y : Math.asin(sy), z : Math.atan2(m._12, m._11) };
		out.x *= 180 / Math.PI;
		out.y *= 180 / Math.PI;
		out.z *= 180 / Math.PI;
		return out;
	}

	function buildModelProps(m : hxd.fmt.hmd.Model) : FbxNode {
		var pos = m.position;
		var q = new Quat();
		pos.loadQuaternion(q);
		q.normalize();
		var e = quatToEuler(q);
		return node("Properties70", null, [
			node("P", [PString("Lcl Translation"), PString("Lcl Translation"), PString(""), PString("A"), PFloat(-pos.x), PFloat(pos.y), PFloat(pos.z)]),
			node("P", [PString("Lcl Rotation"), PString("Lcl Rotation"), PString(""), PString("A"), PFloat(e.x), PFloat(e.y), PFloat(e.z)]),
			node("P", [PString("Lcl Scaling"), PString("Lcl Scaling"), PString(""), PString("A"), PFloat(pos.sx), PFloat(pos.sy), PFloat(pos.sz)]),
		]);
	}

	function buildModelNode(id : Int, name : String, type : String, m : Null<hxd.fmt.hmd.Model>) : FbxNode {
		return node("Model", [PInt(id), PString("Model::" + name), PString(type)], [
			node("Version", [PInt(232)]),
			if( m == null ) node("Properties70", null, []) else buildModelProps(m),
			node("Shading", [PIdent("T")]),
			node("Culling", [PString("CullingOff")]),
		]);
	}

	// ---------------- materials ----------------

	function buildMaterialNode(id : Int, m : hxd.fmt.hmd.Material) : FbxNode {
		var name = m == null || m.name == null ? "Material" : m.name;
		return node("Material", [PInt(id), PString("Material::" + name), PString("")], [
			node("Version", [PInt(102)]),
			node("ShadingModel", [PString("phong")]),
			node("MultiLayer", [PInt(0)]),
			node("Properties70", null, [
				node("P", [PString("DiffuseColor"), PString("Color"), PString(""), PString("A"), PFloat(1), PFloat(1), PFloat(1)]),
				node("P", [PString("DiffuseFactor"), PString("Number"), PString(""), PString("A"), PFloat(1)]),
				node("P", [PString("Shininess"), PString("Number"), PString(""), PString("A"), PFloat(20)]),
				node("P", [PString("SpecularColor"), PString("Color"), PString(""), PString("A"), PFloat(0), PFloat(0), PFloat(0)]),
			]),
		]);
	}

	function connectMaterial(mid : Int, modelId : Int) {
		var id = materialIds.get(mid);
		if( id == null ) {
			id = nextId++;
			materialCount++;
			materialIds.set(mid, id);
			objects.childs.push(buildMaterialNode(id, data.materials[mid]));
		}
		connections.push(node("C", [PString("OO"), PInt(id), PInt(modelId)]));
	}

	// ---------------- geometry ----------------

	function parseGeometry(g : hxd.fmt.hmd.Geometry) : { rows : Array<Float>, stride : Int, posOff : Int, normOff : Int, uvOffs : Array<Int> } {
		if( data.data == null )
			throw "Geometry data is missing";
		var inputs = g.vertexFormat.getInputs();
		var stride = 0, posOff = -1, normOff = -1;
		var uvOffs = [];
		for( i in inputs ) {
			if( i.name == "position" ) posOff = stride;
			if( i.name == "normal" ) normOff = stride;
			if( i.name.indexOf("uv") == 0 ) uvOffs.push(stride);
			stride += i.type.getSize();
		}
		if( posOff < 0 )
			throw "Geometry has no position input";
		var rows = new Array<Float>();
		rows.resize(g.vertexCount * stride);
		var p = 0;
		for( v in 0...g.vertexCount ) {
			var pos = g.vertexPosition + v * g.vertexFormat.strideBytes;
			for( i in inputs ) {
				var comps = i.type.getSize();
				var esz = i.precision.getSize();
				for( k in 0...comps ) {
					rows[p++] = switch( i.precision ) {
					case F32: data.data.getFloat(pos);
					case F16: hxd.BufferFormat.float16to32(data.data.getUInt16(pos));
					case U8: hxd.BufferFormat.floatU8to32(data.data.get(pos));
					case S8: hxd.BufferFormat.floatS8to32(data.data.get(pos));
					}
					pos += esz;
				}
				if( pos & 3 != 0 )
					pos += 4 - (pos & 3);
			}
		}
		return { rows : rows, stride : stride, posOff : posOff, normOff : normOff, uvOffs : uvOffs };
	}

	function layerElement(type : String) : FbxNode {
		return node("LayerElement", null, [
			node("Type", [PString(type)]),
			node("TypedIndex", [PInt(0)]),
		]);
	}

	function buildGeometryNode(id : Int, gid : Int, sub : Int, name : String) : FbxNode {
		var g = data.geometries[gid];
		var parsed = parseGeometry(g);
		var is32 = g.vertexCount > 0x10000;
		var imult = is32 ? 4 : 2;
		var ipos = g.indexPosition;
		for( k in 0...sub )
			ipos += g.indexCounts[k] * imult;
		var count = g.indexCounts[sub];

		var rows = parsed.rows;
		var stride = parsed.stride;
		var verts = [];
		var normals = parsed.normOff >= 0 ? [] : null;
		var uvs = [for( _ in parsed.uvOffs ) []];
		var remap = [];
		var poly = [];
		for( i in 0...count ) {
			var v = is32 ? data.data.getInt32(ipos) : data.data.getUInt16(ipos);
			ipos += imult;
			var nv = remap[v];
			if( nv == null ) {
				nv = Std.int(verts.length / 3);
				remap[v] = nv;
				var rp = v * stride + parsed.posOff;
				verts.push(rows[rp]);
				verts.push(rows[rp + 1]);
				verts.push(rows[rp + 2]);
				for( k in 0...parsed.uvOffs.length ) {
					var up = v * stride + parsed.uvOffs[k];
					uvs[k].push(rows[up]);
					uvs[k].push(1 - rows[up + 1]);
				}
			}
			if( normals != null ) {
				var np = v * stride + parsed.normOff;
				normals.push(rows[np]);
				normals.push(rows[np + 1]);
				normals.push(rows[np + 2]);
			}
			poly.push(nv);
		}
		// triangles last corner is stored inverted in FBX
		for( i in 0...Std.int(poly.length / 3) )
			poly[i * 3 + 2] = -poly[i * 3 + 2] - 1;

		var childs = [];
		childs.push(node("Vertices", [PFloats(verts)]));
		childs.push(node("PolygonVertexIndex", [PInts(poly)]));
		childs.push(node("GeometryVersion", [PInt(124)]));
		if( normals != null )
			childs.push(node("LayerElementNormal", [PInt(0)], [
				node("Version", [PInt(101)]),
				node("Name", [PString("")]),
				node("MappingInformationType", [PString("ByPolygonVertex")]),
				node("ReferenceInformationType", [PString("Direct")]),
				node("Normals", [PFloats(normals)]),
			]));
		for( k in 0...uvs.length )
			childs.push(node("LayerElementUV", [PInt(k)], [
				node("Version", [PInt(101)]),
				node("Name", [PString("map" + (k + 1))]),
				node("MappingInformationType", [PString("ByVertice")]),
				node("ReferenceInformationType", [PString("Direct")]),
				node("UV", [PFloats(uvs[k])]),
			]));
		var layer = node("Layer", [PInt(0)], [node("Version", [PInt(100)])]);
		if( normals != null )
			layer.childs.push(layerElement("LayerElementNormal"));
		for( k in 0...uvs.length )
			layer.childs.push(layerElement("LayerElementUV"));
		layer.childs.push(layerElement("LayerElementMaterial"));
		childs.push(layer);

		return node("Geometry", [PInt(id), PString("Geometry::" + name), PString("Mesh")], childs);
	}

	function getOrCreateGeometry(gid : Int, sub : Int, m : hxd.fmt.hmd.Model) : Int {
		var key = gid + "." + sub;
		var id = geometryIds.get(key);
		if( id != null )
			return id;
		var g = data.geometries[gid];
		var base = m.name == null ? "Geometry" : m.name;
		var name = g.indexCounts.length <= 1 ? base : base + "_" + sub;
		id = nextId++;
		geometryCount++;
		geometryIds.set(key, id);
		objects.childs.push(buildGeometryNode(id, gid, sub, name));
		return id;
	}

	function connectGeometry(m : hxd.fmt.hmd.Model, modelId : Int) {
		var g = data.geometries[m.geometry];
		if( g.indexCounts == null || g.indexCounts.length == 0 )
			return;
		for( sub in 0...g.indexCounts.length ) {
			var geoId = getOrCreateGeometry(m.geometry, sub, m);
			connections.push(node("C", [PString("OP"), PInt(geoId), PInt(modelId)]));
			if( m.materials != null && m.materials.length > sub )
				connectMaterial(m.materials[sub], modelId);
		}
	}

	// ---------------- scene ----------------

	function buildModels() {
		var rootId = nextId++;
		modelCount++;
		objects.childs.push(buildModelNode(rootId, "RootNode", "Null", null));
		connections.push(node("C", [PString("OO"), PInt(rootId), PInt(rootId)]));
		for( i in 0...data.models.length ) {
			var m = data.models[i];
			var id = nextId++;
			modelCount++;
			modelIds[i] = id;
			var name = m.name == null ? "" : m.name;
			var type = m.geometry >= 0 ? "Mesh" : "Null";
			objects.childs.push(buildModelNode(id, name, type, m));
			var parent = m.parent >= 0 && m.parent < modelIds.length ? modelIds[m.parent] : rootId;
			connections.push(node("C", [PString("OO"), PInt(id), PInt(parent)]));
			if( m.geometry >= 0 )
				connectGeometry(m, id);
		}
	}

	public function write(d : hxd.fmt.hmd.Data) {
		data = d;
		objects = node("Objects", null, []);
		connections = [];
		modelIds = [];
		for( i in 0...d.models.length )
			modelIds.push(0);
		geometryIds = new Map();
		materialIds = new Map();
		nextId = 0;
		modelCount = geometryCount = materialCount = 0;

		buildModels();

		var root = node("Root", [PInt(0), PString("Root"), PString("Root")], [
			buildHeaderNode(),
			buildGlobalSettingsNode(),
			writeDefinitions(),
			objects,
			node("Connections", null, connections),
		]);

		out.writeString("; FBX 7.3.0 project file\n");
		out.writeString("; Copyright (C) 1997-2010 Autodesk, Inc. and/or its licensors\n");
		out.writeString("; All rights reserved.\n");
		out.writeString("; ----------------------------------------------------\n\n");
		for( c in root.childs )
			writeNode(c, "");
	}

}

