	static var SIZES = [4,2,1,1];
}

enum abstract InputFormat(Int) {
	public var DFloat = 1;
	public var DVec2 = 2;
	public var DVec3 = 3;
	public var DVec4 = 4;
	public var DBytes4 = 9;
	inline function new(v) this = v;
	public inline function getSize() return this & 7;
	public inline function toInt() return this;
}

class BufferInput {
	public var name : String;
	public var type : InputFormat;
	public var precision : Precision;
	public inline function new( name : String, type : InputFormat, precision = F32 ) {
		this.name = name;
		this.type = type;
		this.precision = precision;
	}
}

class BufferFormat {

	public var stride(get,null) : Int;
	public var strideBytes(get,null) : Int;
	public var hasLowPrecision(get,null) : Bool;
	var inputs : Array<BufferInput>;

	function new( inputs : Array<BufferInput> ) {
		this.inputs = inputs;
	}

	public function getInputs() return inputs;

	static var cache : Array<BufferFormat> = [];

	public static function make( inputs : Array<BufferInput> ) {
		for( fmt in cache ) {
			var same = true;
			var a = fmt.inputs, b = inputs;
			if( a.length != b.length ) continue;
			for( i in 0...a.length )
				if( a[i].name != b[i].name || a[i].type != b[i].type || a[i].precision != b[i].precision ) {
					same = false;
					break;
				}
			if( same ) return fmt;
		}
		var fmt = new BufferFormat(inputs);
		cache.push(fmt);
		return fmt;
	}

	function get_stride() {
		var s = 0;
		for( i in inputs )
			s += i.type.getSize();
		return s;
	}

	function get_strideBytes() {
		var s = 0;
		for( i in inputs ) {
			s += i.type.getSize() * i.precision.getSize();
			if( s & 3 != 0 ) s += 4 - (s & 3);
		}
		return s;
	}

	function get_hasLowPrecision() {
		for( i in inputs )
			if( i.precision != F32 ) return true;
		return false;
	}

	public static function float16to32( v : Int ) : Float {
		var sign = (v & 0x8000) << 16;
		var bits = (v & 0x3FF) << 13;
		var exp = (v & 0x7C00) >> 10;
		if( exp != 0 )
			return haxe.io.FPHelper.i32ToFloat(sign | ((exp + 112) << 23) | bits);
		if( bits == 0 )
			return 0;
		var bitcount = haxe.io.FPHelper.floatToI32(bits) >> 23;
		return haxe.io.FPHelper.i32ToFloat(sign | ((bitcount - 37) << 23) | ((bits << (150 - bitcount)) & 0x7FE000));
	}

	public static function floatS8to32( v : Int ) {
		return (v & 0x80 != 0 ? -1 : 1) * ((v & 0x7F) / 127);
	}

	public static function floatU8to32( v : Int ) {
		return (v & 0xFF) / 255;
	}
}
