			trace("FAIL : " + msg);
		}
	}

	static function test(caseName : String, d : hxd.fmt.hmd.Data) {
		var out = new haxe.io.BytesOutput();
		var w = new hxd.fmt.fbx.Writer(out);
		w.write(d);
		var bytes = out.getBytes();
		var root = hxd.fmt.fbx.Parser.parse(bytes);

		// sections present
		check(root.getAll("FBXHeaderExtension.FBXVersion").length == 1, caseName + " header version");
		check(root.getAll("GlobalSettings").length == 1, caseName + " global settings");
		check(root.getAll("Definitions").length == 1, caseName + " definitions");
		check(root.getAll("Objects.Model").length >= 1, caseName + " models");
		check(root.getAll("Connections").length == 1, caseName + " connections");

		// no material definition
		var mats = root.getAll("Definitions.ObjectType.Material");
		check(mats.length == 0, caseName + " no material definition");
		var matNodes = root.getAll("Objects.Material");
		check(matNodes.length == 0, caseName + " no material nodes");
		var matCons = 0;
		for( c in root.getAll("Connections.C") ) {
			if( c.props.length >= 1 && Std.string(c.props[1]).indexOf("Material::") >= 0 )
				matCons++;
		}
		check(matCons == 0, caseName + " no material connections");

		// defCount consistency
		var defCountNode = root.getAll("Definitions.Count");
		var defCount = defCountNode[0].props[0].toInt();
		var models = root.getAll("Objects.Model");
		var geoms = root.getAll("Objects.Geometry");
		check(defCount == 1 + models.length + geoms.length, caseName + " defCount consistent (" + defCount + ")");

		// definitions object types count
		function objCount(type : String) {
			var n = root.getAll("Definitions.ObjectType").filter(function(o) return Std.string(o.props[0]) == type);
			if( n.length == 0 ) return -1;
			return n[0].get("Count").props[0].toInt();
		}
		check(objCount("Model") == models.length, caseName + " def model count");
		check(objCount("Geometry") == geoms.length, caseName + " def geometry count");

		// geometry validity
		for( g in geoms ) {
			var verts = g.get("Vertices").props[0];
			var poly = g.get("PolygonVertexIndex").props[0];
			var arr : Array<Int> = switch( poly ) { case PInts(v): v; default: []; };
			check(arr.length % 3 == 0, caseName + " polygon count multiple of 3");
			// every 3rd index negative, others valid
			var ok = true;
			for( i in 0...arr.length ) {
				var v = arr[i];
				if( i % 3 == 2 ) { if( v >= 0 ) ok = false; }
				else if( v < 0 ) ok = false;
			}
			check(ok, caseName + " negative index convention");
			var vertCount : Int = switch( verts ) { case PFloats(v): Std.int(v.length / 3); default: -1; };
			for( i in 0...arr.length ) {
				var v = arr[i];
				if( i % 3 == 2 ) v = -v - 1;
				if( v < 0 || v >= vertCount ) ok = false;
			}
			check(ok, caseName + " indices in range");
		}
	}

	static function main() {
		test("single", makeData(false, false, false));
		test("split-multi", makeData(true, false, false));
		test("parent", makeData(false, true, true));
	}
}

