import h3d.mat.Texture;
import h3d.impl.MemoryManager;

class FakeDriver extends h3d.impl.Driver {
	public var allocCount = 0;
	override function allocTexture( t : h3d.mat.Texture ) : h3d.impl.Driver.Texture {
		allocCount++;
		t.t = cast {
			t : null,
			width : t.width,
			height : t.height,
			internalFmt : 0,
			pixelFmt : 0,
			bits : 4,
			bias : 0.,
			bind : 0,
			startMip : 0,
		};
		return t.t;
	}
	override function allocDepthBuffer( b : h3d.mat.Texture ) : h3d.impl.Driver.Texture {
		b.t = cast {
			t : null,
			width : b.width,
			height : b.height,
			internalFmt : 0,
			pixelFmt : 0,
			bits : 4,
			bias : 0.,
			bind : 0,
			startMip : 0,
		};
		return b.t;
	}
	override function isDisposed() : Bool {
		return false;
	}
	override function disposeTexture( t : h3d.mat.Texture ) {
		t.t = null;
	}
}

class M5 {

	static function makeTex(w, h) : Texture {
		return new Texture(w, h, [NoAlloc]);
	}

	static function main() {
		var driver = new FakeDriver();
		var mem = new MemoryManager(driver);
		mem.init();
		var fails = 0;
		function eq(a, b, msg : String) {
			var ok = a == b;
			if( !ok ) fails++;
			trace((ok ? "OK" : "FAIL") + " : " + msg + " (got " + a + ", expected " + b + ")");
		}

		if( hxd.Timer.frameCount > 10000 ) {
			// roll back the frame counter so the test is deterministic
			hxd.Timer.oldTime = hxd.Timer.lastTime;
			hxd.Timer.time = hxd.Timer.oldTime;
		}
		// we cannot easily set frameCount, so compute the current value instead
		var fc = hxd.Timer.frameCount;
		hxd.Timer.frameCount = fc;
		@:privateAccess
		mem.lastAutoDispose = 0;

		// 1) within cooldown : cleanup must not run, lastAutoDispose stays 0
		hxd.Timer.frameCount = 10; // 10 !> 0 + 60
		var t1 = makeTex(8, 8);
		@:privateAccess mem.allocTexture(t1);
		eq(@:privateAccess mem.lastAutoDispose, 0, "within cooldown : cleanup skipped (lastAutoDispose untouched)");
		eq(driver.allocCount, 1, "texture allocated");

		// 2) still within cooldown
		hxd.Timer.frameCount = 40;
		var t2 = makeTex(4, 4);
		@:privateAccess mem.allocTexture(t2);
		eq(@:privateAccess mem.lastAutoDispose, 0, "still within cooldown : cleanup skipped");

		// 3) after cooldown : cleanup runs and refreshes lastAutoDispose
		hxd.Timer.frameCount = 100; // > 0 + 60
		var t3 = makeTex(4, 4);
		@:privateAccess mem.allocTexture(t3);
		eq(@:privateAccess mem.lastAutoDispose, 100, "after cooldown : cleanup ran, lastAutoDispose updated");

