		var t4 = makeTex(4, 4);
		@:privateAccess mem.allocTexture(t4);
		eq(@:privateAccess mem.lastAutoDispose, 100, "just after cleanup : throttled again");

		// 5) explicit forced cleanup still works regardless of cooldown
		@:privateAccess
