		trace((removed == true ? "OK" : "WARN") + " : forced cleanTextures(true) attempted (removed=" + removed + ")");

		// 6) default cooldown value
		eq(mem.autoDisposeCooldown, 60, "default autoDisposeCooldown == 60");

		trace((fails == 0 ? "ALL PASS" : fails + " FAILURES"));
