	static function dist(w : HierarchicalWorld, cx : Float, cy : Float) : Float {
		var ctx = new h3d.scene.RenderContext();
		var cam = new h3d.Camera();
		cam.pos.set(cx, cy, 500.);
		ctx.camera = cam;
		return w.calcDist(ctx);
